 OpenAI Service implementáció

API kliens setup
swift
import Foundation
import OpenAI

class OpenAIService: ObservableObject {
    private var client: OpenAI?
    private let apiKey: String

    init() {
        // FIGYELEM: Soha ne hardcode-old az API kulcsot production-ben!
        // Használj environment variable-t vagy keychain-t
        guard let key = ProcessInfo.processInfo.environment["OPENAI_API_KEY"] else {
            fatalError("OPENAI_API_KEY not found")
        }
        self.apiKey = key
        setupClient()
    }

    private func setupClient() {
        let config = OpenAI.Configuration(
            token: apiKey,
            timeoutInterval: 60.0
        )
        client = OpenAI(configuration: config)
    }

    // Egyszerű request-response
    func sendMessage(_ message: String, 
                     conversationHistory: [Message]) async throws -> String {
        guard let client = client else {
            throw OpenAIError.clientNotInitialized
        }

        // Üzenet history konvertálása OpenAI formátumba
        let messages = conversationHistory.map { msg in
            Chat.Message(
                role: msg.isUser ? .user : .assistant,
                content: msg.content
            )
        } + [Chat.Message(role: .user, content: message)]

        let query = Chat.Query(
            model: .gpt4_o,
            messages: messages,
            temperature: 0.7,
            maxTokens: 2000
        )

        let result = try await client.chats(query: query)

        guard let response = result.choices.first?.message.content else {
            throw OpenAIError.emptyResponse
        }

        return response
    }

    // Streaming response (real-time typing effect)
    func streamMessage(_ message: String,
                      conversationHistory: [Message]) -> AsyncThrowingStream<String, Error> {
        AsyncThrowingStream { continuation in
            Task {
                guard let client = client else {
                    continuation.finish(throwing: OpenAIError.clientNotInitialized)
                    return
                }

                let messages = conversationHistory.map { msg in
                    Chat.Message(
                        role: msg.isUser ? .user : .assistant,
                        content: msg.content
                    )
                } + [Chat.Message(role: .user, content: message)]

                let query = Chat.Query(
                    model: .gpt4_o,
                    messages: messages,
                    temperature: 0.7,
                    maxTokens: 2000
                )

                do {
                    for try await result in client.chatsStream(query: query) {
                        if let content = result.choices.first?.delta.content {
                            continuation.yield(content)
                        }
                    }
                    continuation.finish()
                } catch {
                    continuation.finish(throwing: error)
                }
            }
        }
    }
}

enum OpenAIError: Error {
    case clientNotInitialized
    case emptyResponse
    case invalidAPIKey
}



 ChatViewModel implementáció

ViewModel streaming támogatással
swift
import SwiftUI
import Combine

@MainActor
class ChatViewModel: ObservableObject {
    @Published var messages: [Message] = []
    @Published var currentInput: String = ""
    @Published var isLoading: Bool = false
    @Published var errorMessage: String?

    private let openAIService: OpenAIService
    private let storageService: StorageService

    init(openAIService: OpenAIService = OpenAIService(),
         storageService: StorageService = StorageService()) {
        self.openAIService = openAIService
        self.storageService = storageService
        loadMessages()
    }

    // Üzenet küldése streaming-gel
    func sendMessage() {
        guard !currentInput.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return
        }

        let userMessage = Message(
            content: currentInput,
            isUser: true
        )

        messages.append(userMessage)
        let messageContent = currentInput
        currentInput = ""
        isLoading = true

        // AI válasz placeholder streaming-hez
        let aiMessageId = UUID()
        let aiMessage = Message(
            id: aiMessageId,
            content: "",
            isUser: false,
            isStreaming: true
        )
        messages.append(aiMessage)

        Task {
            do {
                var fullResponse = ""

                for try await chunk in openAIService.streamMessage(
                    messageContent,
                    conversationHistory: messages.filter { !$0.isStreaming }
                ) {
                    fullResponse += chunk

                    // UI frissítés streaming közben
                    if let index = messages.firstIndex(where: { $0.id == aiMessageId }) {
                        messages[index] = Message(
                            id: aiMessageId,
                            content: fullResponse,
                            isUser: false,
                            isStreaming: true
                        )
                    }
                }

                // Streaming befejezése
                if let index = messages.firstIndex(where: { $0.id == aiMessageId }) {
                    messages[index] = Message(
                        id: aiMessageId,
                        content: fullResponse,
                        isUser: false,
                        isStreaming: false
                    )
                }

                saveMessages()
                isLoading = false

            } catch {
                errorMessage = "Error: \(error.localizedDescription)"
                // Hibás üzenet eltávolítása
                messages.removeAll { $0.id == aiMessageId }
                isLoading = false
            }
        }
    }

    // Nem-streaming egyszerű verzió
    func sendMessageSimple() {
        guard !currentInput.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return
        }

        let userMessage = Message(content: currentInput, isUser: true)
        messages.append(userMessage)

        let messageContent = currentInput
        currentInput = ""
        isLoading = true

        Task {
            do {
                let response = try await openAIService.sendMessage(
                    messageContent,
                    conversationHistory: messages
                )

                let aiMessage = Message(content: response, isUser: false)
                messages.append(aiMessage)
                saveMessages()
                isLoading = false

            } catch {
                errorMessage = "Failed to get response: \(error.localizedDescription)"
                isLoading = false
            }
        }
    }

    private func loadMessages() {
        messages = storageService.loadMessages()
    }

    private func saveMessages() {
        storageService.saveMessages(messages)
    }

    func clearConversation() {
        messages.removeAll()
        saveMessages()
    }
}



