 Anthropic Claude integráció iOSen

A Claude az Anthropic által fejlesztett LLM, amely 2025 szeptemberétől natívan elérhető az Xcode 26ban. A Claude Sonnet 4 modell különösen jó hosszabb kontextusok kezelésében és coding feladatokban.[22][4]

 Claude iOS SDK használata

Claude SDK setup 2026ban

Az Anthropic két integrációs lehetőséget kínál iOSre:[4][22]

1. Xcode Intelligence Integration: Beépített Xcode funkció, Claude fiók szükséges
2. API Key Method: Közvetlen API hívások az Anthropic REST APIhoz

API Key alapú megközelítés
swift
import Foundation

class ClaudeService: ObservableObject {
    private let apiKey: String
    private let baseURL = "https://api.anthropic.com/v1/messages"

    init() {
        guard let key = ProcessInfo.processInfo.environment["ANTHROPIC_API_KEY"] else {
            fatalError("ANTHROPIC_API_KEY not found")
        }
        self.apiKey = key
    }

    func sendMessage(_ message: String, 
                     conversationHistory: [Message]) async throws -> String {

        // Claude API messages formátum
        let messages = conversationHistory.map { msg in
            [
                "role": msg.isUser ? "user" : "assistant",
                "content": msg.content
            ]
        } + [["role": "user", "content": message]]

        let requestBody: [String: Any] = [
            "model": "claude-sonnet-4-20250514",
            "max_tokens": 4096,
            "messages": messages,
            "temperature": 0.7
        ]

        var request = URLRequest(url: URL(string: baseURL)!)
        request.httpMethod = "POST"
        request.setValue(apiKey, forHTTPHeaderField: "x-api-key")
        request.setValue("application/json", forHTTPHeaderField: "content-type")
        request.setValue("2023-06-01", forHTTPHeaderField: "anthropic-version")
        request.httpBody = try JSONSerialization.data(withJSONObject: requestBody)

        let (data, response) = try await URLSession.shared.data(for: request)

        guard let httpResponse = response as? HTTPURLResponse,
              httpResponse.statusCode == 200 else {
            throw ClaudeError.requestFailed
        }

        let json = try JSONSerialization.jsonObject(with: data) as? [String: Any]
        guard let content = json?["content"] as? [[String: Any]],
              let text = content.first?["text"] as? String else {
            throw ClaudeError.invalidResponse
        }

        return text
    }

    // Streaming support Claude-hoz
    func streamMessage(_ message: String,
                      conversationHistory: [Message]) -> AsyncThrowingStream<String, Error> {
        AsyncThrowingStream { continuation in
            Task {
                let messages = conversationHistory.map { msg in
                    [
                        "role": msg.isUser ? "user" : "assistant",
                        "content": msg.content
                    ]
                } + [["role": "user", "content": message]]

                let requestBody: [String: Any] = [
                    "model": "claude-sonnet-4-20250514",
                    "max_tokens": 4096,
                    "messages": messages,
                    "temperature": 0.7,
                    "stream": true
                ]

                var request = URLRequest(url: URL(string: baseURL)!)
                request.httpMethod = "POST"
                request.setValue(apiKey, forHTTPHeaderField: "x-api-key")
                request.setValue("application/json", forHTTPHeaderField: "content-type")
                request.setValue("2023-06-01", forHTTPHeaderField: "anthropic-version")
                request.httpBody = try? JSONSerialization.data(withJSONObject: requestBody)

                do {
                    let (bytes, _) = try await URLSession.shared.bytes(for: request)

                    for try await line in bytes.lines {
                        if line.hasPrefix("data: ") {
                            let jsonString = String(line.dropFirst(6))
                            if let data = jsonString.data(using: .utf8),
                               let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                               let delta = json["delta"] as? [String: Any],
                               let text = delta["text"] as? String {
                                continuation.yield(text)
                            }
                        }
                    }
                    continuation.finish()
                } catch {
                    continuation.finish(throwing: error)
                }
            }
        }
    }
}

enum ClaudeError: Error {
    case requestFailed
    case invalidResponse
}



 Claude App Integration (iOS 18.2+)

Az iOS 18.2 óta a Claude alkalmazás Apple Health integrációval rendelkezik, amely lehetővé teszi egészségügyi adatok elemzését:[23][8]

swift
import HealthKit

class ClaudeHealthIntegration {
    let healthStore = HKHealthStore()

    func requestHealthAuthorization() async throws {
        let typesToRead: Set<HKObjectType> = [
            HKObjectType.quantityType(forIdentifier: .stepCount)!,
            HKObjectType.quantityType(forIdentifier: .heartRate)!,
            HKObjectType.categoryType(forIdentifier: .sleepAnalysis)!
        ]

        try await healthStore.requestAuthorization(toShare: [], read: typesToRead)
    }

    func fetchHealthDataForClaude() async throws -> String {
        // Health adatok lekérése és formázása Claude-nak
        // Ez példakód, a valóságban összetettebb query-k kellenek

        let stepType = HKQuantityType.quantityType(forIdentifier: .stepCount)!
        let calendar = Calendar.current
        let now = Date()
        let startOfDay = calendar.startOfDay(for: now)

        let predicate = HKQuery.predicateForSamples(
            withStart: startOfDay,
            end: now,
            options: .strictStartDate
        )

        return try await withCheckedThrowingContinuation { continuation in
            let query = HKStatisticsQuery(
                quantityType: stepType,
                quantitySamplePredicate: predicate,
                options: .cumulativeSum
            ) { _, result, error in
                if let error = error {
                    continuation.resume(throwing: error)
                    return
                }

                if let sum = result?.sumQuantity() {
                    let steps = sum.doubleValue(for: HKUnit.count())
                    continuation.resume(returning: "Today's steps: \(Int(steps))")
                } else {
                    continuation.resume(returning: "No step data available")
                }
            }

            healthStore.execute(query)
        }
    }
}



