Firebase AI Logic használata chathez
swift
import Foundation
import FirebaseAILogic

class GeminiChatService: ObservableObject {
    private var chat: Chat?

    init() {
        setupChat()
    }

    private func setupChat() {
        // Gemini model konfiguráció
        let config = GenerationConfig(
            temperature: 0.7,
            topP: 0.95,
            topK: 40,
            maxOutputTokens: 2048
        )

        let model = GenerativeModel(
            name: "gemini-2.0-flash-exp",
            generationConfig: config
        )

        // Chat session létrehozása
        chat = model.startChat()
    }

    // Egyszerű message küldés
    func sendMessage(_ message: String) async throws -> String {
        guard let chat = chat else {
            throw GeminiError.chatNotInitialized
        }

        let response = try await chat.sendMessage(message)

        guard let text = response.text else {
            throw GeminiError.emptyResponse
        }

        return text
    }

    // Streaming response
    func streamMessage(_ message: String) -> AsyncThrowingStream<String, Error> {
        AsyncThrowingStream { continuation in
            Task {
                guard let chat = chat else {
                    continuation.finish(throwing: GeminiError.chatNotInitialized)
                    return
                }

                do {
                    let responseStream = chat.sendMessageStream(message)

                    for try await chunk in responseStream {
                        if let text = chunk.text {
                            continuation.yield(text)
                        }
                    }

                    continuation.finish()
                } catch {
                    continuation.finish(throwing: error)
                }
            }
        }
    }

    // Multimodális input (text + kép)
    func sendMessageWithImage(_ text: String, 
                              image: UIImage) async throws -> String {
        guard let chat = chat else {
            throw GeminiError.chatNotInitialized
        }

        // Kép konvertálása megfelelő formátumba
        guard let imageData = image.jpegData(compressionQuality: 0.8) else {
            throw GeminiError.imageConversionFailed
        }

        let imagePart = ModelContent.Part.data(
            mimetype: "image/jpeg",
            imageData
        )

        let response = try await chat.sendMessage(text, imagePart)

        guard let responseText = response.text else {
            throw GeminiError.emptyResponse
        }

        return responseText
    }

    // Chat history reset
    func resetChat() {
        setupChat()
    }
}

enum GeminiError: Error {
    case chatNotInitialized
    case emptyResponse
    case imageConversionFailed
}



