 Repository Pattern

Az API hívások és adatkezelés elkülönítése:

swift
protocol ChatRepository {
    func sendMessage(_ message: String, history: [Message]) async throws -> String
    func saveConversation(_ conversation: Conversation) throws
    func loadConversations() throws -> [Conversation]
}

class ChatRepositoryImpl: ChatRepository {
    private let apiService: AIService
    private let storageService: StorageService

    init(apiService: AIService, storageService: StorageService) {
        self.apiService = apiService
        self.storageService = storageService
    }

    func sendMessage(_ message: String, history: [Message]) async throws -> String {
        return try await apiService.sendMessage(message, conversationHistory: history)
    }

    func saveConversation(_ conversation: Conversation) throws {
        try storageService.saveConversation(conversation)
    }

    func loadConversations() throws -> [Conversation] {
        return try storageService.loadConversations()
    }
}


