 UserDefaults egyszerű esetekhez

Kis mennyiségű adat tárolása (settings, API keys):
swift
class UserDefaultsStorage {
    private let defaults = UserDefaults.standard

    func saveAPIKey(_ key: String) {
        defaults.set(key, forKey: "api_key")
    }

    func loadAPIKey() -> String? {
        return defaults.string(forKey: "api_key")
    }

    func saveConversations(_ conversations: [Conversation]) throws {
        let encoder = JSONEncoder()
        let data = try encoder.encode(conversations)
        defaults.set(data, forKey: "conversations")
    }

    func loadConversations() throws -> [Conversation] {
        guard let data = defaults.data(forKey: "conversations") else {
            return []
        }

        let decoder = JSONDecoder()
        return try decoder.decode([Conversation].self, from: data)
    }
}


