 CloudKit sync többeszközös szinkronizációhoz

iCloud sync bekapcsolása:
swift
import CloudKit

class CloudKitService {
    private let container = CKContainer.default()
    private let privateDatabase: CKDatabase

    init() {
        privateDatabase = container.privateCloudDatabase
    }

    func saveConversation(_ conversation: Conversation) async throws {
        let record = CKRecord(recordType: "Conversation")
        record["title"] = conversation.title
        record["createdAt"] = conversation.createdAt

        try await privateDatabase.save(record)
    }

    func fetchConversations() async throws -> [Conversation] {
        let query = CKQuery(recordType: "Conversation", predicate: NSPredicate(value: true))
        let results = try await privateDatabase.records(matching: query)

        return results.matchResults.compactMap { _, result in
            guard let record = try? result.get() else { return nil }

            return Conversation(
                id: UUID(),
                title: record["title"] as? String ?? "",
                createdAt: record["createdAt"] as? Date ?? Date()
            )
        }
    }
}


